function groupAnagrams(words) {
  const map = new Map();
  for (let word of words) {
    const key = word;            // BUG: key is the raw word, not sorted letters
    map.set(key, word);          // BUG: overwrites instead of pushing to a list
  }
  return Array.from(map.values());
}

const result = groupAnagrams(["eat", "tea", "ate", "tan", "nat"]);
console.log("groups=" + result.length);
